const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');
const ui={screen:document.querySelector('#screen'),start:document.querySelector('#startBtn'),berries:document.querySelector('#berryCount'),health:document.querySelector('#health'),objective:document.querySelector('#objective'),hint:document.querySelector('#hint'),toast:document.querySelector('#toast'),action:document.querySelector('#actionBtn')};
const W=1200,H=780,world={w:1900,h:1320};let scale=1,cam={x:0,y:0},last=0,running=false,won=false,toastTimer=0,steps=0;
const keys=new Set(),berries=[],trees=[],flowers=[],foxes=[];
let player={x:195,y:1075,vx:0,vy:0,r:23,health:3,face:1,invuln:0,anim:0};
const berrySpots=[[410,970],[690,770],[1000,620],[1300,440],[1535,265]];
const pathPoints=[[135,1160],[250,1090],[400,1020],[510,930],[585,850],[730,790],[830,700],[940,655],[1060,620],[1140,545],[1230,490],[1375,430],[1455,355],[1510,270],[1555,205]];
function seeded(n){let x=Math.sin(n*127.1+41.7)*43758.5453;return x-Math.floor(x)}
function resize(){const box=document.querySelector('#game').getBoundingClientRect();scale=Math.min(box.width/W,box.height/H);const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
function reset(){player={x:195,y:1075,vx:0,vy:0,r:23,health:3,face:1,invuln:0,anim:0};berries.length=0;berrySpots.forEach((p,i)=>berries.push({x:p[0],y:p[1],got:false,phase:i*1.7}));foxes.length=0;[[590,785,1.3],[1040,616,1.05],[1370,405,.9]].forEach((f,i)=>foxes.push({x:f[0],y:f[1],homeX:f[0],homeY:f[1],phase:i*2.2,speed:f[2],r:21}));won=false;ui.berries.textContent='0 / 5';ui.health.textContent='♥ ♥ ♥';ui.objective.innerHTML='Encuentra <b>5 bayas de luna</b> y abre el arco antiguo.'}
function makeWorld(){trees.length=0;flowers.length=0;for(let i=0;i<180;i++){let x=40+seeded(i+1)*1820,y=40+seeded(i+301)*1240;if(pathDistance(x,y)<77)continue;if(Math.hypot(x-195,y-1075)<110||Math.hypot(x-1555,y-205)<115)continue;trees.push({x,y,r:25+seeded(i+701)*19,type:Math.floor(seeded(i+101)*3),tone:seeded(i+501)})}for(let i=0;i<260;i++){let x=seeded(i+801)*1900,y=seeded(i+1101)*1320;if(pathDistance(x,y)<63)continue;flowers.push({x,y,t:seeded(i+1401),s:2+seeded(i+1601)*3})}}
function pathDistance(x,y){let d=1e9;for(const p of pathPoints)d=Math.min(d,Math.hypot(p[0]-x,p[1]-y));return d}
makeWorld();reset();resize();addEventListener('resize',resize);
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.2}
function start(){if(won)reset();running=true;ui.screen.classList.add('hidden');last=performance.now();requestAnimationFrame(frame)}ui.start.addEventListener('click',start);
addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(!running&&['enter',' '].includes(k))start();if(running&&k==='e')interact()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
document.querySelectorAll('.touch-btn[data-dir]').forEach(b=>{let key={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(key);b.classList.add('down');b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{keys.delete(key);b.classList.remove('down')})});ui.action.addEventListener('pointerdown',e=>{e.preventDefault();interact()});
function interact(){if(!running)return;const gate=Math.hypot(player.x-1555,player.y-205);if(gate<120){if(berries.every(b=>b.got)){win()}else toast(`El arco pide ${5-berries.filter(b=>b.got).length} baya${5-berries.filter(b=>b.got).length===1?'':'s'} más ✨`);return}let nearest=null,dist=1000;for(const f of foxes){const d=Math.hypot(f.x-player.x,f.y-player.y);if(d<dist){dist=d;nearest=f}}if(nearest&&dist<95){nearest.stunned=2;toast('¡Puf! El zorro salió corriendo.');return}if(Math.hypot(player.x-195,player.y-1075)<100)toast('¡Vamos! Sigue el sendero de luciérnagas.');else toast('Sigue el camino y busca los destellos dorados.');}
function win(){won=true;running=false;ui.screen.innerHTML='<section class="card"><div class="eyebrow">El bosque vuelve a brillar</div><div class="bear-art">🐻✨</div><h1>¡Lo lograste,<br><span>guardián del bosque!</span></h1><p>Las cinco bayas encendieron el arco y la luna volvió a sonreír. Bruno siempre tendrá un hogar mágico.</p><div class="controls"><span>Bayas reunidas: <b>5 / 5</b></span><span>Amigos salvados: <b>¡todo el bosque!</b></span></div><button class="primary" id="againBtn">Jugar otra vez</button><p class="footnote">La senda de la luna · Fin de la aventura</p></section>';ui.screen.classList.remove('hidden');document.querySelector('#againBtn').addEventListener('click',()=>{reset();ui.screen.innerHTML='<section class="card"><div class="eyebrow">Una aventura acogedora</div><div class="bear-art">🐻</div><h1>Bruno y el<br><span>bosque dormido</span></h1><p>La luna ha apagado el viejo arco del bosque. Guía a Bruno por el sendero, recoge bayas luminosas y devuelve la magia a casa.</p><div class="controls"><span><b>WASD</b> o flechas · moverse</span><span><b>E</b> · interactuar</span><span>Evita a los zorros 🦊</span></div><button class="primary" id="startBtn">Empezar aventura</button><p class="footnote">También puedes jugar con los controles táctiles.</p></section>';document.querySelector('#startBtn').addEventListener('click',start);start()})}
function update(dt){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);let mag=Math.hypot(dx,dy)||1;dx/=mag;dy/=mag;const speed=205;player.vx+=(dx*speed-player.vx)*Math.min(1,dt*11);player.vy+=(dy*speed-player.vy)*Math.min(1,dt*11);if(!dx&&!dy){player.vx*=Math.max(0,1-dt*7);player.vy*=Math.max(0,1-dt*7)}if(Math.abs(player.vx)>4)player.face=Math.sign(player.vx);player.anim+=dt*Math.hypot(player.vx,player.vy)*.045;let nx=clamp(player.x+player.vx*dt,35,world.w-35),ny=clamp(player.y+player.vy*dt,35,world.h-35);for(const t of trees){const d=Math.hypot(nx-t.x,ny-(t.y+9)),min=player.r+t.r*.62;if(d<min&&d>0){const push=(min-d)/d;nx+=(nx-t.x)*push;ny+=(ny-(t.y+9))*push}}player.x=clamp(nx,35,world.w-35);player.y=clamp(ny,35,world.h-35);if(player.invuln>0)player.invuln-=dt;
for(const b of berries){b.phase+=dt;if(!b.got&&Math.hypot(player.x-b.x,player.y-b.y)<37){b.got=true;let n=berries.filter(q=>q.got).length;ui.berries.textContent=`${n} / 5`;toast(['¡Baya de luna! ✨','¡Qué dulce! 🌙','Otra luz para el bosque 💫','¡El arco casi despierta! ✨','¡Ya tienes todas! Ve al arco 🌟'][n-1]);if(n===5)ui.objective.innerHTML='¡Todas reunidas! Ve al <b>arco de piedra</b> en el norte.'}}
for(const f of foxes){f.phase+=dt;if(f.stunned>0){f.stunned-=dt;continue}let wander=Math.sin(f.phase*f.speed)*56;f.x=f.homeX+wander;f.y=f.homeY+Math.cos(f.phase*f.speed*.65)*29;if(player.invuln<=0&&Math.hypot(player.x-f.x,player.y-f.y)<player.r+f.r-3){player.health--;player.invuln=1.6;let a=Math.atan2(player.y-f.y,player.x-f.x);player.x=clamp(player.x+Math.cos(a)*54,35,world.w-35);player.y=clamp(player.y+Math.sin(a)*54,35,world.h-35);ui.health.textContent='♥ '.repeat(player.health)+'♡ '.repeat(3-player.health);toast(player.health?'¡Cuidado con los zorros! 🦊':'¡Bruno necesita descansar!');if(!player.health){running=false;ui.screen.classList.remove('hidden');ui.screen.innerHTML='<section class="card"><div class="eyebrow">Un pequeño descanso</div><div class="bear-art">🐻💤</div><h1>¡Casi lo<br><span>consigues!</span></h1><p>Los zorros son traviesos. Inténtalo otra vez y esquívalos en el sendero.</p><button class="primary" id="retryBtn">Volver a intentar</button><p class="footnote">Consejo: mantén las flechas para correr.</p></section>';document.querySelector('#retryBtn').addEventListener('click',()=>{reset();ui.screen.classList.remove('hidden');ui.screen.innerHTML='<section class="card"><div class="eyebrow">Una aventura acogedora</div><div class="bear-art">🐻</div><h1>Bruno y el<br><span>bosque dormido</span></h1><p>La luna ha apagado el viejo arco del bosque. Guía a Bruno por el sendero, recoge bayas luminosas y devuelve la magia a casa.</p><div class="controls"><span><b>WASD</b> o flechas · moverse</span><span><b>E</b> · interactuar</span><span>Evita a los zorros 🦊</span></div><button class="primary" id="startBtn">Empezar aventura</button><p class="footnote">También puedes jugar con los controles táctiles.</p></section>';document.querySelector('#startBtn').addEventListener('click',start)})}}}
if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}
if(Math.hypot(player.x-1555,player.y-205)<105){ui.hint.innerHTML=berries.every(b=>b.got)?'<kbd>E</kbd> para abrir el arco':'Acércate al arco cuando tengas las 5 bayas'}else if(Math.hypot(player.x-195,player.y-1075)<100){ui.hint.innerHTML='<kbd>WASD</kbd> / <kbd>← ↑ ↓ →</kbd> para caminar'}cam.x=clamp(player.x-W/2,0,world.w-W);cam.y=clamp(player.y-H/2,0,world.h-H)}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}

function frame(now){if(!running)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw(now/1000);requestAnimationFrame(frame)}
function draw(time){let box=document.querySelector('#game').getBoundingClientRect(),cw=box.width,ch=box.height,sx=cw/W,sy=ch/H;ctx.setTransform(sx,0,0,sy,0,0);ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(-cam.x,-cam.y);drawGround(time);drawPath(time);for(const f of flowers){ctx.globalAlpha=.54;ctx.fillStyle=['#f7d56d','#f1b58c','#e4d7a2'][Math.floor(f.t*3)];ctx.beginPath();ctx.arc(f.x,f.y,f.s,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;drawGate(time);let things=[...trees.map(t=>({y:t.y,kind:'tree',obj:t})),...berries.filter(b=>!b.got).map(b=>({y:b.y,kind:'berry',obj:b})),...foxes.map(f=>({y:f.y,kind:'fox',obj:f})),{y:player.y,kind:'bear',obj:player}].sort((a,b)=>a.y-b.y);for(const it of things){if(it.kind==='tree')drawTree(it.obj);else if(it.kind==='berry')drawBerry(it.obj,time);else if(it.kind==='fox')drawFox(it.obj,time);else drawBear(it.obj,time)}drawFireflies(time);ctx.restore();let vign=ctx.createRadialGradient(W/2,H/2,180,W/2,H/2,720);vign.addColorStop(0,'#00000000');vign.addColorStop(1,'#0c241e44');ctx.fillStyle=vign;ctx.fillRect(0,0,W,H)}
function drawGround(t){ctx.fillStyle='#547b4d';ctx.fillRect(0,0,world.w,world.h);for(let y=0;y<world.h;y+=110){for(let x=0;x<world.w;x+=120){let n=seeded(x*2+y*3);ctx.fillStyle=n>.5?'#88a45b0b':'#173e3210';ctx.beginPath();ctx.ellipse(x+30+n*40,y+22,25+n*22,12+n*12,n*3,0,Math.PI*2);ctx.fill()}}// moonlit glade
let g=ctx.createRadialGradient(1555,210,35,1555,210,340);g.addColorStop(0,'#e6d99424');g.addColorStop(1,'#e6d99400');ctx.fillStyle=g;ctx.fillRect(1200,0,600,530);
}
function drawPath(t){ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(pathPoints[0][0],pathPoints[0][1]);for(let i=1;i<pathPoints.length;i++)ctx.lineTo(pathPoints[i][0],pathPoints[i][1]);ctx.strokeStyle='#c8ad7650';ctx.lineWidth=118;ctx.stroke();ctx.strokeStyle='#d5bc8954';ctx.lineWidth=89;ctx.stroke();ctx.strokeStyle='#e2d09f30';ctx.lineWidth=68;ctx.stroke();for(let i=0;i<75;i++){let p=pathPoints[Math.floor(i/5)%pathPoints.length],off=(i%5-2)*18+Math.sin(t*1.6+i*3)*3;ctx.fillStyle=i%2?'#f1dea125':'#8c704a29';ctx.beginPath();ctx.ellipse(p[0]+off,p[1]+(i%3-1)*13,3+(i%4),2+(i%2),i,0,Math.PI*2);ctx.fill()}}
function drawTree(t){let sway=Math.sin(t*.7+t.x)*1.5;ctx.fillStyle='#193d2d55';ctx.beginPath();ctx.ellipse(t.x,t.y+27,t.r*.92,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#654a32';ctx.beginPath();ctx.roundRect(t.x-7,t.y-3,14,39,5);ctx.fill();let cols=t.type===0?['#315f40','#40734a','#557f4c']:t.type===1?['#426945','#597d4d','#6d8750']:['#26533e','#376548','#4a7851'];for(let j=0;j<3;j++){let r=t.r*(1-j*.16);ctx.fillStyle=cols[j];ctx.beginPath();ctx.ellipse(t.x+(j-1)*t.r*.34+sway*(j+1),t.y-j*t.r*.48,r*.78,r*.7,0,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#ffffff12';ctx.beginPath();ctx.ellipse(t.x-t.r*.35,t.y-t.r*.57,t.r*.18,t.r*.35,-.3,0,Math.PI*2);ctx.fill()}
function drawBerry(b,t){let pulse=1+Math.sin(t*4+b.phase)*.12;ctx.save();ctx.translate(b.x,b.y+Math.sin(t*2+b.phase)*3);ctx.globalAlpha=.18;ctx.fillStyle='#ffd76a';ctx.beginPath();ctx.arc(0,0,26*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#294c34';ctx.beginPath();ctx.ellipse(0,10,14,6,0,0,Math.PI*2);ctx.fill();for(let i=-1;i<=1;i++){ctx.fillStyle=i===0?'#facd62':'#edaa55';ctx.beginPath();ctx.arc(i*8,0+(Math.abs(i)*2),7,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#fff0ad';ctx.beginPath();ctx.arc(-2,-3,2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#8ead55';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-5);ctx.quadraticCurveTo(3,-12,9,-10);ctx.stroke();ctx.restore()}
function drawBear(p,t){ctx.save();ctx.translate(p.x,p.y+Math.sin(p.anim)*1.5);if(p.invuln>0&&Math.floor(t*13)%2===0)ctx.globalAlpha=.38;ctx.scale(p.face,1);let walking=Math.min(1,Math.hypot(p.vx,p.vy)/140),bounce=Math.sin(p.anim*2)*2*walking;ctx.translate(0,bounce);ctx.fillStyle='#1f3a2a55';ctx.beginPath();ctx.ellipse(0,20,27,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3d2920';ctx.beginPath();ctx.arc(-18,-5,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#70472d';ctx.beginPath();ctx.ellipse(0,2,22,23,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8d5d39';ctx.beginPath();ctx.ellipse(0,6,13,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#70472d';ctx.beginPath();ctx.arc(3,-22,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#4b3023';for(const x of [-9,14]){ctx.beginPath();ctx.arc(x,-34,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e0a36d';ctx.beginPath();ctx.arc(x,-34,3.8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#70472d'}ctx.fillStyle='#f0cca0';ctx.beginPath();ctx.ellipse(13,-17,11,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2c211c';ctx.beginPath();ctx.ellipse(20,-21,4,3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2b201a';ctx.beginPath();ctx.arc(8,-25,2.1,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#3b261e';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(13,-13);ctx.quadraticCurveTo(16,-9,19,-13);ctx.stroke();ctx.fillStyle='#e9a1a0';ctx.beginPath();ctx.roundRect(-7,-3,14,9,4);ctx.fill();ctx.strokeStyle='#e3bb6c';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-2,-2);ctx.lineTo(1,4);ctx.lineTo(6,-2);ctx.stroke();ctx.restore()}
function drawFox(f,t){ctx.save();ctx.translate(f.x,f.y);if(f.stunned>0){ctx.globalAlpha=.48+Math.sin(t*15)*.25;ctx.rotate(Math.sin(t*4)*.3)}ctx.fillStyle='#223c2b55';ctx.beginPath();ctx.ellipse(0,15,24,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d97943';ctx.beginPath();ctx.ellipse(0,0,20,14,Math.sin(t*2+f.phase)*.07,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e68d4f';ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(-14,-25);ctx.lineTo(-1,-14);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(7,-8);ctx.lineTo(15,-24);ctx.lineTo(17,-9);ctx.closePath();ctx.fill();ctx.fillStyle='#f4ddbd';ctx.beginPath();ctx.ellipse(4,4,11,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f0d7b6';ctx.beginPath();ctx.ellipse(-18,-1,12,8,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#29231c';ctx.beginPath();ctx.arc(9,-5,2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#322019';ctx.beginPath();ctx.arc(16,0,3,0,Math.PI*2);ctx.fill();if(f.stunned>0){ctx.fillStyle='#ffdd75';ctx.font='bold 17px sans-serif';ctx.fillText('✦',-4,-28)}ctx.restore()}
function drawGate(t){let x=1555,y=205;ctx.fillStyle='#244e405e';ctx.beginPath();ctx.ellipse(x,y+47,86,20,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#496d50';ctx.lineWidth=20;ctx.beginPath();ctx.arc(x,y+18,57,Math.PI,0);ctx.lineTo(x+57,y+53);ctx.moveTo(x-57,y+18);ctx.lineTo(x-57,y+53);ctx.stroke();ctx.strokeStyle='#789065';ctx.lineWidth=5;ctx.beginPath();ctx.arc(x,y+18,57,Math.PI,0);ctx.stroke();ctx.fillStyle='#e7d495';for(let i=0;i<5;i++){let a=Math.PI+(i/4)*Math.PI;ctx.beginPath();ctx.arc(x+Math.cos(a)*57,y+18+Math.sin(a)*57,3,0,Math.PI*2);ctx.fill()}ctx.fillStyle=berries.every(b=>b.got)?`rgba(255,221,125,${.35+Math.sin(t*3)*.13})`:'#243a31aa';ctx.beginPath();ctx.roundRect(x-35,y+9,70,43,[35,35,3,3]);ctx.fill();if(berries.every(b=>b.got)){ctx.strokeStyle='#ffe18b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y+23,23+Math.sin(t*3)*4,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ffe698';ctx.font='21px sans-serif';ctx.textAlign='center';ctx.fillText('✧',x,y+30)}else{ctx.fillStyle='#d9c989';ctx.font='19px sans-serif';ctx.textAlign='center';ctx.fillText('☾',x,y+35)}ctx.textAlign='left'}
function drawFireflies(t){for(let i=0;i<25;i++){let x=player.x+Math.sin(t*.5+i*14)*245,y=player.y+Math.cos(t*.7+i*9)*190,glow=.3+.45*(.5+.5*Math.sin(t*3+i*8));ctx.globalAlpha=glow;ctx.fillStyle='#f9e58d';ctx.beginPath();ctx.arc(x,y,1.5+(i%3),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function frame(now){if(!running)return;let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw(now/1000);requestAnimationFrame(frame)}
// Render a living forest behind the title screen too.
function idleFrame(now){if(!running){draw(now/1000);requestAnimationFrame(idleFrame)}}requestAnimationFrame(idleFrame);
</script>
</body>
</html>

